/** 
 * Kicks the given <tt>ChatRoomMember</tt>.
 * @param chatRoomMember the chat room member to kick
 * @param reason the reason of the kick
 * @throws OperationFailedException if we are not joined or we don't haveenough privileges to kick a participant.
 */
public void kickParticipant(final ChatRoomMember chatRoomMember,final String reason) throws OperationFailedException {
  this.parentProvider.getIrcStack().kickParticipant(this,chatRoomMember,reason);
}
